	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
	clock    Clock
}

// New creates a Limiter with the given capacity and refill rate (tokens/sec).
func New(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, ErrInvalidCapacity
	}
	if rate <= 0 {
		return nil, ErrInvalidRate
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		capacity: float64(capacity),
		rate:     rate,
		tokens:   float64(capacity),
		clock:    clock,
	}, nil
}

// AllowN reports whether n tokens are available at time now, consuming them if so.
func (l *Limiter) AllowN(n int) bool {
	return l.AllowNAt(n, l.clock.Now())
}

// AllowNAt is AllowN with an explicit timestamp (useful for tests).
func (l *Limiter) AllowNAt(n int, now time.Time) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	if !l.last.IsZero() {
		elapsed := now.Sub(l.last).Seconds()
		if elapsed > 0 {
			l.tokens += elapsed * l.rate
			if l.tokens > l.capacity {
				l.tokens = l.capacity
			}
		}
	}
	l.last = now

	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for observability).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}
